NAME = 'GerLeoNA28: Leonberger Bibel, NT (NA28)'
BOOK = 'Ephesians'

CHAPTERS = {
    1: {
        1: 'Paulus, ein Apostel von Christus Jesus durch den Willen Gottes. /An die Heiligen und Gläubigen in Christus Jesus, die in Ephesus leben: /',
        2: 'Gnade [sei mit] euch und Frieden von Gott, unserem Vater, und von dem Herrn Jesus Christus!',
        3: 'Gepriesen [sei] der Gott und Vater unseres Herrn Jesus Christus, der uns in Christus gesegnet hat mit allem geistlichen Segen in den himmlischen [Sphären],',
        4: 'schließlich hat er uns in ihm erwählt vor Grundlegung der Welt, dass wir heilig und makellos seien vor ihm in Liebe,',
        5: 'nachdem er uns für sich zur Sohnschaft vorherbestimmt hat durch Jesus Christus, nach dem Wohlgefallen seines Willens,',
        6: 'zum Lob seiner herrlichen Gnade, mit der er uns in dem Geliebten beschenkt hat.',
        7: 'In ihm haben wir die Erlösung durch sein Blut, die Vergebung [unserer] Verfehlungen, nach dem Reichtum seiner Gnade,',
        8: 'die er in uns vermehrt hat in aller Weisheit und Einsicht,',
        9: 'indem er uns das Geheimnis seines Willens bekannt gemacht hat nach seinem Wohlgefallen, den er sich in ihm vorgenommen hat,',
        10: 'zur Verwaltung bei der Erfüllung der Zeiten, nämlich in Christus alles zusammenzufassen, was in den Himmeln und was auf der Erde [ist] – in ihm.',
        11: 'Durch den wir auch zu Erben gemacht wurden, weil wir vorherbestimmt waren nach dem Plan dessen, der alles nach dem Ratschluss seines Willens bewirkt,',
        12: 'damit wir zum Lob seiner Herrlichkeit leben, die wir zuvor auf Christus gehofft haben.',
        13: 'In ihm [seid] auch ihr, die ihr das Wort der Wahrheit gehört habt, die gute Nachricht von eurer Rettung … in ihm seid ihr, schon als ihr gläubig geworden seid, versiegelt worden mit dem heiligen Geist der Verheißung,',
        14: 'der eine Anzahlung ist auf unser Erbe, bis zur Erlösung von [Gottes] Besitz, zum Lob seiner Herrlichkeit.',
        15: 'Deshalb: Nachdem auch ich von eurem Glauben an den Herrn Jesus und von eurer Liebe zu allen Heiligen gehört habe,',
        16: 'höre ich nicht auf, für euch zu danken und euch ‹in Erinnerung zu rufen› in meinen Gebeten,',
        17: 'dass der Gott unseres Herrn Jesus Christus, der Vater der Herrlichkeit, euch einen Geist der Weisheit und der Offenbarung gebe, [um zu wachsen] in seiner Erkenntnis,',
        18: 'nachdem er die Augen eures Herzens erleuchtet hat, damit ihr wisst, was die Hoffnung seiner Berufung ist, was der Reichtum seines herrlichen Erbes unter den Heiligen [ist],',
        19: 'und was die überragende Größe seiner Kraft für uns Glaubende [ist], gemäß dem Wirken der Macht seiner Stärke,',
        20: 'die in Christus gewirkt und ihn von den Toten auferweckt und ihn in den himmlischen [Sphären] zu seiner Rechten gesetzt hat,',
        21: 'über jede Urgewalt und Macht und Kraft und Herrschaft und jeden genannten Namen, nicht nur in diesem Zeitalter, sondern auch in dem zukünftigen;',
        22: 'und er hat alles unter seine Füße untergeordnet und hat ihn als Haupt über alles der Gemeinde gegeben,',
        23: 'welche sein Leib ist, die Fülle dessen, der alles in allem erfüllt.',
    },
    2: {
        1: 'Auch ihr wart tot durch eure Verfehlungen und Sünden,',
        2: 'in denen ihr früher gelebt habt nach dem Lauf dieser Welt, nach dem mächtigen Fürsten der Luft, [nämlich] dem Geist, der jetzt in den Söhnen des Unglaubens wirkt,',
        3: 'unter denen auch wir alle früher gelebt haben in den Begierden unseres Fleisches, weil wir den Willen des Fleisches und des Verstandes ausgeführt haben, und wir waren von Natur aus Kinder des Zorns, wie die übrigen [Menschen];',
        4: 'Gott aber, der reich ist an Erbarmen – aufgrund seiner großen Liebe, mit der er uns geliebt hat –,',
        5: 'hat auch uns, die wir tot waren in [unseren] Verfehlungen, zusammen mit Christus lebendig gemacht (durch Gnade seid ihr gerettet),',
        6: 'und mitauferweckt und miteingesetzt in den himmlischen [Sphären] in Christus Jesus,',
        7: 'damit er in den kommenden Zeitaltern den überragenden Reichtum seiner Gnade zeigt, durch [seine] Freundlichkeit uns gegenüber in Christus Jesus.',
        8: 'Denn aus Gnade seid ihr errettet worden durch Glauben, und das nicht von euch aus – Gottes Geschenk [ist es],',
        9: 'nicht aus Werken, damit sich niemand rühmt.',
        10: 'Denn wir sind sein Kunstwerk, erschaffen in Christus Jesus zu guten Werken, die Gott vorbereitet hat, damit wir ‹sie mit Leben füllen›.',
        11: 'Darum erinnert euch daran, dass früher ihr, die Heiden im Fleisch, die ihr „Unbeschnittenheit“genannt werdet von der sogenannten „Beschneidung“, die mit der Hand am Fleisch vorgenommen wird …',
        12: 'dass ihr zu jener Zeit ohne Christus wart, entfremdet vom Bürgerrecht Israels und Fremde der Bünde der Verheißung, keine Hoffnung habend und ohne Gott in der Welt.',
        13: 'Jetzt aber, in Christus Jesus, seid ihr, die ihr früher fern wart, nahe gebracht durch das Blut des Christus.',
        14: 'Denn er ist unser Friede, der die beiden eins gemacht und die abgrenzende Trennwand – die Feindschaft – durch sein Fleisch aufgelöst',
        15: '[und] das Gesetz der Gebote und Satzungen abgeschafft hat, damit er die zwei in sich zu einem neuen Menschen schafft, um Frieden zu stiften,',
        16: 'und die beiden in einem Leib für Gott durch das Kreuz versöhnt hat, indem er die Feindschaft in sich selbst getötet hat,',
        17: 'und als er kam, hat er euch die gute Nachricht verkündet: Frieden den Fernen und Frieden den Nahen!',
        18: 'Denn durch ihn haben wir beide in einem Geist Zugang zum Vater.',
        19: 'Also seid ihr nun nicht länger Fremde und Gäste, sondern ihr seid Mitbürger der Heiligen und Hausgenossen Gottes,',
        20: 'erbaut auf dem Fundament der Apostel und Propheten, wobei Christus Jesus selbst der Eckstein ist,',
        21: 'auf dem der ganze Bau zusammengefügt wird und wächst, hin zu einem heiligen Tempel im Herrn,',
        22: '[und] auf dem auch ihr mit eingebaut werdet zu einer Behausung Gottes im Geist.',
    },
    3: {
        1: 'Deswegen [bin] ich, Paulus, der Gefangene des Christus Jesus für euch, die Heiden …',
        2: 'Ihr habt doch sicher von der Verwaltung der Gnade Gottes gehört, die mir für euch gegeben wurde,',
        3: 'weil mir durch eine Offenbarung das Geheimnis bekannt gemacht wurde, wie ich zuvor in [aller] Kürze geschrieben habe,',
        4: 'damit ihr, wenn ihr es lest, meine Einsicht in das Geheimnis des Christus verstehen könnt',
        5: '(was in anderen Generationen den Menschenkindern nicht bekannt gemacht wurde, wie es jetzt seinen heiligen Aposteln und Propheten durch den Geist offenbart worden ist):',
        6: 'dass die Heiden in Christus Jesus Miterben und Mitglieder und Mitgenossen der Verheißung sind durch die gute Nachricht,',
        7: 'deren Diener ich geworden bin nach dem Geschenk der Gnade Gottes, die mir gegeben worden ist entsprechend dem Wirken seiner Kraft.',
        8: 'Mir, dem Geringsten von allen Heiligen ist diese Gnade gegeben worden! –, um den Heiden den unermesslichen Reichtum des Christus zu verkünden',
        9: 'und alle darin zu erleuchten, was die Verwaltung des Geheimnisses [ist], das seit Ewigkeiten verborgen ist in Gott, der alles geschaffen hat,',
        10: 'damit jetzt den Gewalten und den Mächten in den himmlischen [Sphären] durch die Gemeinde die vielfältige Weisheit Gottes bekannt gemacht wird,',
        11: 'gemäß der Absicht der Ewigkeiten, die er in Christus Jesus, unserem Herrn, ausgeführt hat,',
        12: 'in dem wir die Zuversicht und den Zugang haben im Vertrauen durch seine Treue.',
        13: 'Darum bitte ich [euch], nicht zu verzagen in meinen Bedrängnissen für euch, die eure Herrlichkeit bedeuten.',
        14: 'Deswegen beuge ich meine Knie vor dem Vater,',
        15: 'von dem jede Familie in den Himmeln und auf der Erde benannt wird,',
        16: 'dass er es euch ermöglicht, nach dem Reichtum seiner Herrlichkeit durch seinen Geist mit Kraft gefestigt zu werden am inneren Menschen,',
        17: 'sodass Christus durch den Glauben in euren Herzen wohnt, in Liebe verwurzelt und gegründet;',
        18: 'sodass ihr mit allen Heiligen imstande seid zu begreifen, was die Breite und Länge und Höhe und Tiefe [ist],',
        19: 'und die Liebe Christi zu kennen, die die Erkenntnis übertrifft; sodass ihr erfüllt werdet bis zur ganzen Fülle Gottes.',
        20: 'Dem aber, der unendlich viel mehr tun kann als alles, was wir erbitten oder erdenken, nach der Kraft, die in uns wirkt,',
        21: 'ihm [sei] die Ehre in der Gemeinde und in Christus Jesus für alle Generationen, ‹auf immer und ewig›! Amen.',
    },
    4: {
        1: 'Ich, der Gefangene im Herrn, fordere euch nun auf, würdig der Berufung zu leben, mit der ihr berufen worden seid –',
        2: 'mit aller Demut und Sanftmütigkeit; mit Geduld; einander in Liebe ertragend;',
        3: 'darum bemüht, die Einheit des Geistes zu bewahren mit dem Band des Friedens.',
        4: '[Es ist] ein Leib und ein Geist (so wie ihr auch berufen worden seid in einer Hoffnung eurer Berufung),',
        5: 'ein Herr, ein Glaube, eine Taufe,',
        6: 'ein Gott und Vater von allen, der über allen und durch alle und in allen [ist].',
        7: 'Aber jedem Einzelnen von uns ist die Gnade gegeben worden nach dem Maß des Geschenks von Christus.',
        8: 'Darum heißt es: „Er ist hinaufgestiegen in die Höhe und hat ‹einen Tross an Gefangenen› gefangen genommen, / er hat den Menschen Gaben gegeben.“',
        9: 'Aber das „er ist hinaufgestiegen“, was bedeutet es, wenn nicht, dass er auch hinabgestiegen ist zu den unteren Gefilden der Erde?',
        10: 'Der hinabgestiegen ist, ist derselbe, der auch hinaufgestiegen ist über alle Himmel, um alles zu erfüllen.',
        11: 'Und er selbst gab manche als Apostel, manche als Propheten, manche als Evangelisten, manche als Hirten und Lehrer,',
        12: 'zur Ausrüstung der Heiligen für das Werk des Dienstes, für die Auferbauung des Leibes Christi,',
        13: 'bis wir alle zur Einheit des Glaubens und der Erkenntnis des Sohnes Gottes gelangen, zum Erwachsensein, zum Maß der Reife der Fülle Christi,',
        14: 'damit wir nicht länger Unmündige sind, hin- und hergerissen und von jedem Wind der Lehre umhergetrieben durch das Verwirrspiel der Menschen, durch [ihre] Hinterlistigkeit, [anfällig] für die Machenschaft des Irrtums.',
        15: 'Aber indem wir in Liebe wahrhaftig sind, lasst uns in allem zu ihm hin wachsen, der das Haupt ist, Christus,',
        16: 'von dem aus der ganze Leib – zusammengefügt und durch jedes unterstützende Gelenk verbunden gemäß dem Wirken im Maß jedes einzelnen Gliedes – das Wachstum des Leibes zustande bringt, zur Auferbauung seiner selbst in Liebe.',
        17: 'Folgendes sage und bezeuge ich nun im Herrn: dass ihr nicht länger so lebt, wie die Heiden leben, in der Nichtigkeit ihres Sinnes,',
        18: 'die hinsichtlich des Verstandes verfinstert sind, dem Leben Gottes entfremdet aufgrund der Unwissenheit, die unter ihnen besteht wegen der Verhärtung ihres Herzens,',
        19: 'welche abgestumpft sind und sich der Ausschweifung ausgeliefert haben, zur Ausübung aller Unreinheit in Habgier.',
        20: 'Ihr aber habt Christus so nicht kennengelernt,',
        21: 'wenn ihr tatsächlich von ihm gehört und in ihm gelehrt worden seid, wie es Wahrheit in Jesus ist,',
        22: 'dass ihr, ‹was den früheren Lebenswandel betrifft›, den alten Menschen abgelegt habt, der zerstört wird entsprechend der trügerischen Begierden,',
        23: 'und erneuert werdet im Geist eures Verstandes',
        24: 'und den neuen Menschen angezogen habt, der Gott entsprechend in wahrer Gerechtigkeit und Heiligkeit geschaffen worden ist.',
        25: 'Darum legt die Lüge ab und redet die Wahrheit – ein jeder mit seinem Nächsten –, weil wir untereinander Glieder sind.',
        26: 'Zürnt, aber sündigt nicht! Die Sonne soll nicht untergehen über eurem Zorn;',
        27: 'und gebt dem Teufel keinen Raum!',
        28: 'Wer stiehlt, soll nicht mehr stehlen, sondern sich vielmehr bemühen, mit seinen eigenen Händen Gutes zu bewirken, damit er [genügend] hat, um dem [etwas] mitzugeben, der es nötig hat.',
        29: 'Keinerlei faules Wort soll von eurem Mund ausgehen, sondern wenn [möglich], dann ein gutes zur Auferbauung, ‹wo es nottut›, damit es denen Gnade gibt, die es hören.',
        30: 'Und betrübt den heiligen Geist Gottes nicht, mit dem ihr versiegelt worden seid für den Tag der Erlösung.',
        31: 'Alle Bitterkeit und Wut und Zorn und Geschrei und Lästerei soll fern von euch sein, samt aller Bosheit.',
        32: 'Seid hingegen freundlich [und] herzlich zueinander! Verzeiht euch gegenseitig, wie auch Gott euch in Christus verziehen hat.',
    },
    5: {
        1: 'Werdet also Nachahmer Gottes, als geliebte Kinder,',
        2: 'und lebt in Liebe, so wie auch Christus uns geliebt hat und sich selbst für uns hingegeben hat, als Opfergabe und Schlachtopfer, zu einem süßlichen Wohlgeruch für Gott.',
        3: 'Unzucht aber und alle Unreinheit oder Habgier sollen nicht einmal unter euch genannt werden, wie es sich für Heilige gehört,',
        4: 'auch Obszönität und dummes Gerede oder Schabernack, die nicht angemessen waren, sondern vielmehr Danksagung.',
        5: 'Denn Folgendes sollt ihr wissen und erkennen: Jeder Unzüchtige oder Unreine oder Habgierige (das heißt: ein Götzendiener) hat kein Erbe im Königreich Christi und Gottes.',
        6: 'Niemand soll euch mit leeren Worten verleiten; denn deshalb kommt der Zorn Gottes über die Kinder des Ungehorsams.',
        7: 'Darum seid nicht ihre Mitgenossen!',
        8: 'Denn früher wart ihr Finsternis, aber jetzt [seid ihr] Licht im Herrn; lebt als Kinder des Lichts –',
        9: 'denn die Frucht des Lichts [besteht] in lauter Güte und Gerechtigkeit und Wahrheit –,',
        10: 'indem ihr prüft, was dem Herrn gefällt,',
        11: 'und verbündet euch nicht mit den unfruchtbaren Werken der Finsternis, sondern deckt sie sogar vielmehr auf!',
        12: 'Denn was heimlich von ihnen geschieht, ist sogar auszusprechen unsittlich;',
        13: 'alles aber, was vom Licht aufgedeckt wird, wird sichtbar,',
        14: 'denn alles, was sichtbar wird, ist Licht. Darum heißt es: „Wache auf, der du schläfst, / und stehe auf von den Toten, / dann wird Christus dir scheinen.“',
        15: 'Achtet also genau darauf, wie ihr lebt – nicht als unweise, sondern als weise [Menschen] –,',
        16: 'indem ihr die Zeit auskauft, weil die Tage böse sind.',
        17: 'Deshalb seid nicht töricht, sondern versteht, was der Wille des Herrn [ist]!',
        18: 'Und betrinkt euch nicht mit Wein, worin Ausschweifung besteht, sondern werdet erfüllt mit dem Geist,',
        19: 'sodass ihr euch gegenseitig mit Psalmen und Hymnen und geistlichen Liedern anredet [und] für den Herrn singt und musiziert in euren Herzen;',
        20: 'sodass ihr dem Gott und Vater jederzeit für alles dankt im Namen unseres Herrn Jesus Christus;',
        21: 'sodass ihr euch einander unterordnet in der Ehrfurcht vor Christus.',
        22: 'Ihr Frauen, [ordnet euch] euren Ehemännern [unter] wie dem Herrn,',
        23: 'denn der Ehemann ist das Haupt der Ehefrau, wie auch Christus das Haupt der Gemeinde [ist] – er [ist] der Retter des Leibes.',
        24: 'Doch wie sich die Gemeinde Christus unterordnet, so auch die Ehefrauen in allem [ihren] Ehemännern.',
        25: 'Ihr Männer, liebt [eure] Ehefrauen, wie auch Christus die Gemeinde geliebt hat und sich selbst für sie hingegeben hat,',
        26: 'um sie zu heiligen und rein zu machen durch das Wasserbad im Wort,',
        27: 'sodass er sich selbst die verherrlichte Gemeinde präsentiert, die weder Flecken noch Falten noch etwas derartiges hat, sondern dass sie heilig und makellos sei.',
        28: 'So sehr sind auch die Männer verpflichtet, ihre Ehefrauen zu lieben wie ihren eigenen Körper. Wer seine Ehefrau liebt, liebt sich selbst.',
        29: 'Denn niemand hat je sein eigenes Fleisch gehasst, sondern er ernährt und pflegt es, wie auch Christus die Gemeinde,',
        30: 'weil wir Glieder seines Leibes sind.',
        31: '„Deswegen wird ein Mann Vater und Mutter verlassen und sich seiner Frau anhängen, und die zwei werden zu einem Fleisch werden.“',
        32: 'Dieses Geheimnis ist groß; ich aber beziehe es auf Christus und die Gemeinde.',
        33: 'Jedoch auch ihr als Einzelne: Ein jeder soll seine Ehefrau so sehr lieben wie sich selbst, die Ehefrau wiederum, dass sie den Ehemann respektiert.',
    },
    6: {
        1: 'Ihr Kinder, gehorcht euren Eltern im Herrn, denn das ist recht!',
        2: '„Ehre deinen Vater und deine Mutter“(welches das erste Gebot mit einer Verheißung ist),',
        3: '„sodass es dir gut geht und du ‹lange leben wirst› in dem Land.“',
        4: 'Und ihr Väter, macht eure Kinder nicht zornig, sondern erzieht sie in der Unterweisung und Belehrung des Herrn!',
        5: 'Ihr Sklaven, gehorcht den irdischen Herren mit Furcht und Zittern, mit der Aufrichtigkeit eures Herzens, als ob Christus [euer Gehorsam gelten würde],',
        6: 'nicht als „Augendienst“wie Einschmeichler [ihn leisten], sondern wie Diener Christi, die den Willen Gottes von Herzen tun;',
        7: 'dient mit gutem Willen, als ob dem Herrn [dieser Dienst gelten würde] und nicht Menschen,',
        8: 'weil ihr wisst, dass ein jeder, wenn er etwas Gutes tut, dies vom Herrn zurückbekommen wird, ob Sklave oder freier [Mensch].',
        9: 'Und ihr Herren, tut dasselbe ihnen gegenüber, indem ihr die Androhung [von Strafe] aufgebt, weil ihr wisst, dass sowohl deren als auch euer Herr in den Himmeln ist, und Parteilichkeit gibt es bei ihm nicht.',
        10: 'Im Übrigen: Werdet stark im Herrn und in der Macht seiner Stärke!',
        11: 'Zieht die Waffenrüstung Gottes an, damit ihr bestehen könnt gegen die Machenschaften des Teufels!',
        12: 'Denn unser Kampf ist nicht gegen Blut und Fleisch, sondern gegen die Gewalten, gegen die Mächte, gegen die Weltherrscher dieser Finsternis, gegen die geistigen [Kräfte] der Bosheit in den himmlischen [Sphären].',
        13: 'Deshalb ergreift die Waffenrüstung Gottes, damit ihr imstande seid, an dem bösen Tag zu widerstehen und, nachdem ihr alles bewirkt habt, fest zu stehen.',
        14: 'Steht also fest, eure Lenden umgürtet mit Wahrheit und bekleidet mit dem Brustpanzer der Gerechtigkeit',
        15: 'und die Füße gestiefelt mit der Bereitschaft [zur Verbreitung] der guten Nachricht des Friedens,',
        16: 'und nehmt in allem das Schild des Glaubens, mit dem ihr alle brennenden Pfeile des Bösen werdet auslöschen können;',
        17: 'empfangt auch den Helm der Rettung und das Schwert des Geistes, der das Wort Gottes ist.',
        18: 'Betet durch alles Bitten und Flehen zu aller Zeit im Geist, und dazu seid wachsam mit aller Ausdauer und Flehen für alle Heiligen',
        19: 'und für mich, damit mir beim Öffnen meines Mundes ein Wort gegeben wird, um mit Freimütigkeit das Geheimnis der guten Nachricht bekannt zu machen,',
        20: 'für die ich ein Botschafter in Ketten bin, damit ich in ihm freimütig bin, wie ich reden muss.',
        21: 'Und damit auch ihr ‹meine Umstände› kennt (was ich tue), wird euch Tychikus, der geliebte Bruder und treue Diener im Herrn, alles wissen lassen;',
        22: 'den habe ich zu eben diesem [Zweck] zu euch geschickt, damit ihr wisst, ‹was uns betrifft›, und er eure Herzen tröstet.',
        23: 'Friede [sei] den Geschwistern und Liebe mit Glauben von Gott dem Vater und von dem Herrn Jesus Christus.',
        24: 'Die Gnade [sei] mit allen, die unseren Herrn Jesus Christus lieben in Unvergänglichkeit.',
    },
}
